steps.script:
# The point every step below aims at, and how far inside the Telemon's bubble it
# is. Positive = illegal today.
var telemon = Vector2(600, 250)
var aim = Vector2(600, 690)
var bubble_px = (9.0 + (100.0 / 2.0) / 25.4 + (32.0 / 2.0) / 25.4) * 40.0
return snappedf(bubble_px - aim.distance_to(telemon), 0.1)

# ...and it still pushes an inside-the-bubble aim back out while the pad is
# active and the preference is off. Called directly rather than by injecting
# mouse motion, which would flip the active device back to mouse & keyboard.
var dc = tree.current_scene.deployment_controller
var model = GameState.state.units.U_KOMMANDOS_H.models[1]
var held = dc._clamped_placement_position(Vector2(600, 690), model, 0.0)
var best = 1000.0
for enemy in GameState.get_enemy_model_positions(2):
	var edge = held.distance_to(Vector2(enemy.x, enemy.y)) / 40.0 - (32.0 / 2.0) / 25.4 - (float(enemy.base_mm) / 2.0) / 25.4
	if edge < best:
		best = edge
tree.current_scene.set_meta("ds_pad_probe", "pad=%s setting=%s held=%s edge=%.3f\"" % [str(InputDeviceManager.is_pad_active()), str(SettingsService.placement_clamp_to_exclusion), str(held), best])
return snappedf(best, 0.01)

# Part D — the whole pad path for real, not a direct call: the left stick drove
# the virtual cursor to a point 1.5" inside the Telemon's exclusion bubble, and
# the ghost is held on the 9" line with the setting still OFF. This is the half
# of the report a thumbstick makes impossible to do by hand.
var m = tree.current_scene
var dc = m.deployment_controller
var g = dc.ghost_sprite
var cursor = dc._get_world_mouse_position()
var moved = cursor.distance_to(m.get_meta("ds_pad_cursor_before"))
var best = 1000.0
for enemy in GameState.get_enemy_model_positions(2):
	var edge = g.position.distance_to(Vector2(enemy.x, enemy.y)) / 40.0 - (32.0 / 2.0) / 25.4 - (float(enemy.base_mm) / 2.0) / 25.4
	if edge < best:
		best = edge
m.set_meta("ds_pad_glide_probe", "pad=%s cursor_active=%s setting=%s cursor=%s (stick moved it %.0fpx) ghost=%s edge=%.3f\"" % [str(InputDeviceManager.is_pad_active()), str(VirtualCursor.is_cursor_active()), str(SettingsService.placement_clamp_to_exclusion), str(cursor), moved, str(g.position), best])
if not VirtualCursor.is_cursor_active():
	return -1.0
if moved < 50.0:
	return -2.0
if g.clamp_origin_world == null:
	return -3.0
if not g.is_valid_position:
	return -4.0
return snappedf(best, 0.01)
